const e="allemagne",o=1,n={habitants:"les Allemands",adjectif:"allemand",adjectifF:"allemande",devise:"Einigkeit und Recht und Rechtschreibreform, dans cet ordre de lecture",medaillon:"DE",chaineInfo:"DE AKTUELL",hymne:"Vive la Fédération"},s={chambre:"Bundestag",chambreLong:"Bundestag fédéral",chefGouvernement:"Chancelier fédéral",chefEtat:"Président fédéral (rôle protocolaire)",passageForce:{label:"Question de confiance",description:"Le Chancelier demande aux députés de lui renouveler leur confiance sur un texte : s'ils refusent, il peut demander la dissolution, ce qui rend l'exercice très convaincant.",news:"Question de confiance sur {loi} : le Bundestag vote avec une attention soudaine"},censure:{label:"Motion de défiance constructive",description:"On ne peut renverser le Chancelier qu'en élisant simultanément son successeur : la défiance allemande exige un remplaçant, un programme et un plan de table.",news:"Motion de défiance constructive : l'opposition a un nom, il lui manque 38 voix"},dissolution:{label:"Dissolution du Bundestag",description:"Après une question de confiance perdue, le Président fédéral peut dissoudre le Bundestag. Il le fait lentement, en relisant la Loi fondamentale à voix haute.",news:"Le Bundestag est dissous : les affiches sont déjà prêtes, évidemment"}},a={type:"federales",label:"Élections fédérales",intro:"Quatre semaines de campagne, trois débats télévisés de quatre-vingt-dix minutes et un duel de promesses sur les trains, l'énergie et les formulaires. Personne ne crie, tout le monde annote.",adversaires:[{id:"adv-de-1",name:"Heidrun Vogelsang",parti:"Union Fédérale Chrétienne",style:"chiffres",punchlines:["Mon adversaire promet tout : j'ai les tableaux qui prouvent qu'il ne tient pas.","Je ne crois pas aux promesses, je crois aux annexes.","Un frein, c'est comme une ceinture : on se plaint, puis on arrive vivant."],genre:"f"},{id:"adv-de-2",name:"Matthias Rheinfeld",parti:"Parti Social Rhénan",style:"emotion",punchlines:["Les familles ne sont pas des lignes budgétaires, et les trains ne sont pas des hypothèses.","Mon adversaire a un plan pour les ponts ; moi, j'ai un plan pour ceux qui les traversent.","La cogestion, c'est quand tout le monde est fatigué mais décide ensemble."],genre:"m"},{id:"adv-de-3",name:"Lena Gartenstein",parti:"Verts du Nouvel Horizon",style:"attaque",punchlines:["Mon adversaire a un projet pour 2050 et une voiture pour 1998.","Vous n'avez pas peur du climat, vous avez peur du formulaire de subvention.","Un hiver doux, c'est votre bilan en trois mots."],genre:"f"}],nuitElectorale:"À Berlin, la soirée électorale dure trois heures, deux projections et une coalition annoncée avant l'heure : on attend les négociations de la nuit suivante, puis celles du mois suivant."},t=[{id:"allemagne-frein-dette-assoupli",title:"Assouplissement du frein à l'endettement",domain:"institutions",description:"Autoriser un peu de déficit pour réparer les ponts. Le frein à l'endettement, inscrit dans la Loi fondamentale, proteste en trois exemplaires signés.",accroche:"Le frein reste serré, on desserre seulement l'écrou qui coince depuis dix ans.",effects:{budget:-4,economie:3,popularite:1,assemblee:-3},delayed:[{delay:4,effects:{budget:-2},label:"Les intérêts de la dette arrivent, ponctuels eux"}],groupStance:{"union-federale":-.7,"social-rhenan":.8,"verts-federaux":.9,"liberaux-marche":-1,"alternative-nationale":-.4,"gauche-unie":.6},streetAnger:.2},{id:"allemagne-plan-ponctualite-rail",title:"Plan de ponctualité du Rail fédéral",domain:"ecologie",description:"Investir des milliards pour que le train de 8 h 12 arrive avant 9 h 40. Les voyageurs, prudents, ont déjà prévu une correspondance de secours.",accroche:"Un train à l'heure, c'est promis : seule l'heure reste à définir.",effects:{budget:-6,ecologie:2,economie:1,popularite:1},delayed:[{delay:4,effects:{popularite:2,economie:1},label:"Un train arrive à l'heure : la presse envoie un reporter"}],groupStance:{"union-federale":.2,"social-rhenan":.7,"verts-federaux":.8,"liberaux-marche":-.3,"alternative-nationale":-.2,"gauche-unie":.5},streetAnger:.1},{id:"allemagne-fin-du-fax",title:"Abolition du fax administratif",domain:"numerique",description:"Remplacer les fax des services publics par un système numérique. Les imprimantes thermiques demandent un délai de deuil de dix-huit mois.",accroche:"Le fax prend sa retraite, il a bien mérité de ne plus sonner en vain.",effects:{economie:2,budget:-3,popularite:1,assemblee:1},delayed:[{delay:3,effects:{economie:1,popularite:1},label:"Premier formulaire envoyé sans papier à en-tête"}],groupStance:{"union-federale":.4,"social-rhenan":.5,"verts-federaux":.6,"liberaux-marche":.9,"alternative-nationale":0,"gauche-unie":.2},streetAnger:0},{id:"allemagne-sortie-charbon-acceleree",title:"Sortie accélérée du charbon",domain:"energie",description:"Fermer les dernières mines et centrales à charbon avant la date prévue. Les régions concernées réclament un plan, une prime et si possible un musée.",accroche:"Le charbon s'éteint, avec tous les égards dus à un vieux serviteur noirci.",effects:{ecologie:4,economie:-3,pouvoirAchat:-2,cohesion:-3,popularite:-2},delayed:[{delay:4,effects:{ecologie:1,economie:1},label:"Reconversion des bassins : les éoliennes tournent"}],groupStance:{"union-federale":-.3,"social-rhenan":.2,"verts-federaux":1,"liberaux-marche":.3,"alternative-nationale":-.9,"gauche-unie":.3},streetAnger:.5},{id:"allemagne-programme-scolaire-commun",title:"Programme scolaire commun aux seize Länder",domain:"education",description:"Un seul programme de la Baltique à la Bavière. Les ministres régionaux de l'éducation, jaloux de leurs prérogatives, défendent leurs manuels comme des frontières.",accroche:"Seize Länder, un seul programme, et dix-sept avis sur la page de garde.",effects:{cohesion:2,popularite:-3,assemblee:-3},delayed:[{delay:4,effects:{cohesion:1,economie:1},label:"Les élèves de Brême et de Munich lisent enfin le même poème"}],groupStance:{"union-federale":-.2,"social-rhenan":.6,"verts-federaux":.5,"liberaux-marche":.3,"alternative-nationale":-.7,"gauche-unie":.4},streetAnger:.3},{id:"allemagne-reconnaissance-diplomes",title:"Reconnaissance accélérée des diplômes étrangers",domain:"travail",description:"Réduire de dix-huit à trois mois la validation des qualifications. Le formulaire A-38, lui, n'a pas été consulté et conserve ses sept annexes.",accroche:"Un diplôme étranger obtient enfin son tampon, avant la fin de la formation continue.",effects:{economie:3,cohesion:1,popularite:-2,budget:-1},delayed:[{delay:4,effects:{economie:1,budget:1},label:"Les artisans manquants trouvent enfin leur tampon"}],groupStance:{"union-federale":.3,"social-rhenan":.6,"verts-federaux":.7,"liberaux-marche":.8,"alternative-nationale":-1,"gauche-unie":.3},streetAnger:.3},{id:"allemagne-allegement-pme",title:"Allègement bureaucratique des PME",domain:"travail",description:"Supprimer une obligation de déclaration sur trois pour les entreprises familiales. Les cabinets de conseil en conformité préparent leur communiqué de deuil.",accroche:"Le formulaire A38 sera désormais remplacé par un formulaire A37, nettement plus léger.",effects:{economie:3,budget:-3,popularite:1},delayed:[{delay:3,effects:{economie:1},label:"Les entreprises familiales embauchent, un stagiaire aux formulaires"}],groupStance:{"union-federale":.8,"social-rhenan":.1,"verts-federaux":0,"liberaux-marche":1,"alternative-nationale":.4,"gauche-unie":-.5},streetAnger:.1},{id:"allemagne-frein-aux-loyers",title:"Frein aux loyers dans les grandes villes",domain:"logement",description:"Plafonner les loyers à la relocation dans les métropoles. Les locataires applaudissent, les propriétaires découvrent un attachement soudain à la liberté contractuelle.",accroche:"Les loyers freinent, les locataires accélèrent, et la cage d'escalier arbitre.",effects:{pouvoirAchat:3,popularite:2,economie:-3,budget:-1},delayed:[{delay:4,effects:{economie:-2,pouvoirAchat:-1},label:"Les constructeurs patientent à l'ombre du plafond"}],groupStance:{"union-federale":-.5,"social-rhenan":.8,"verts-federaux":.5,"liberaux-marche":-1,"alternative-nationale":-.2,"gauche-unie":.9},streetAnger:.3},{id:"allemagne-vitesse-autoroute",title:"Limitation de vitesse sur autoroute",domain:"securite",description:"Instaurer une limite générale sur les autoroutes sans plafond. Une partie de la population y voit une atteinte aux libertés fondamentales, une autre une idée de bon sens.",accroche:"Une vitesse maximale sur l'autoroute : l'aiguille du compteur crie à l'injustice.",effects:{securite:3,ecologie:2,popularite:-6,cohesion:-2},delayed:[{delay:3,effects:{securite:1,ecologie:1},label:"Moins d'accidents, plus de colère au volant"}],groupStance:{"union-federale":-.5,"social-rhenan":.4,"verts-federaux":.9,"liberaux-marche":-.8,"alternative-nationale":-.8,"gauche-unie":.4},streetAnger:.6},{id:"allemagne-cogestion-numerique",title:"Cogestion dans les plateformes numériques",domain:"travail",description:"Étendre les conseils d'entreprise aux géants du numérique et aux livreurs. Les start-up découvrent la réunion préparatoire de la réunion préparatoire.",accroche:"Même l'algorithme aura un comité d'entreprise, avec procès-verbal en trois exemplaires.",effects:{cohesion:2,pouvoirAchat:1,economie:-2,popularite:1},delayed:[{delay:4,effects:{cohesion:1,economie:-1},label:"Premier comité d'entreprise dans un coworking"}],groupStance:{"union-federale":-.4,"social-rhenan":.9,"verts-federaux":.6,"liberaux-marche":-.7,"alternative-nationale":-.3,"gauche-unie":.8},streetAnger:.2}],i=JSON.parse(`[{"id":"allemagne-frein-dette-blocage","title":"Le frein à l'endettement bloque tout","category":"economie","description":"Un pont, deux écoles et une centrale sont en attente de crédits, mais le frein à l'endettement tient bon. Les juristes de Karlsruhe-bis sortent leurs commentaires de texte.","weight":5,"minTurn":2,"conditions":[{"gauge":"budget","op":"<","value":48}],"choices":[{"id":"fonds-special","label":"Créer un fonds spécial hors budget","description":"Un fonds « exceptionnel » qui finance l'ordinaire.","effects":{"budget":-3,"economie":3,"popularite":1,"assemblee":-3},"delayed":[{"delay":3,"effects":{"budget":-2},"label":"Les juristes demandent le budget du budget"}],"news":"Un fonds spécial est créé : le frein est contourné avec élégance"},{"id":"clause-urgence","label":"Invoquer la clause d'urgence","description":"Suspendre la règle pour un an, solennellement.","effects":{"budget":-5,"popularite":2,"economie":2,"assemblee":-2},"news":"Clause d'urgence : le frein cède, comme prévu au chapitre 12"},{"id":"serrer-ceinture","label":"Respecter la règle à la lettre","description":"Reporter les travaux. Les ponts patienteront.","effects":{"budget":2,"economie":-3,"popularite":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Le pont ferme définitivement le mardi"}],"news":"Le gouvernement respecte le frein, le pont prend de l'âge"}]},{"id":"allemagne-trains-en-retard","title":"Le train de 8 h 12 arrive demain","category":"social","description":"Le Rail fédéral annonce une ponctualité de 58 %, chiffre qu'il qualifie de « stable ». Les usagers sont invités à développer un attachement affectif aux quais.","weight":6,"choices":[{"id":"plan-urgence","label":"Plan d'urgence pour les voies","description":"Mobiliser de l'argent, des ingénieurs et un calendrier public.","effects":{"budget":-5,"popularite":2,"ecologie":1,"economie":1},"delayed":[{"delay":4,"effects":{"popularite":1},"label":"Une ligne retrouve son horaire d'origine"}],"news":"Plan d'urgence ferroviaire : les voyageurs attendent de voir"},{"id":"excuses","label":"Présenter des excuses solennelles","description":"Un communiqué d'excuses signé, relu et tamponné.","effects":{"popularite":-2,"cohesion":1},"news":"Excuses du gouvernement : le train de 17 h 04 les reçoit en gare... à 18 h"},{"id":"prix-reduit","label":"Billet à prix réduit pour compenser","description":"Offrir le retard à moitié prix.","effects":{"pouvoirAchat":2,"popularite":1,"budget":-4},"news":"Retards indemnisés : on peut désormais perdre du temps à tarif réduit"}]},{"id":"allemagne-lander-bras-de-fer","title":"Les Länder bloquent au Bundesrat","category":"politique","description":"Plusieurs gouvernements régionaux refusent un texte au Bundesrat, chacun pour une raison différente, toutes également impérieuses. Les couloirs bruissent de compromis non écrits.","weight":5,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":52}],"choices":[{"id":"negocier-lander","label":"Négocier région par région","description":"Un transfert de crédits pour chaque Land mécontent.","effects":{"assemblee":3,"budget":-4,"popularite":1},"news":"Marathon de négociations : seize Länder, seize contreparties"},{"id":"commission-mediation","label":"Saisir la commission de médiation","description":"Renvoyer le texte à une commission qui l'amendera avec méthode.","effects":{"assemblee":1,"popularite":-2,"cohesion":1},"delayed":[{"delay":3,"effects":{"assemblee":1},"label":"Un compromis sort de la commission, fatigué mais valide"}],"news":"Commission de médiation saisie : verdict attendu entre Pâques et l'automne"},{"id":"passer-outre","label":"Déclarer le texte non soumis à leur accord","description":"Une lecture audacieuse de la Loi fondamentale.","effects":{"assemblee":-5,"popularite":-2,"cohesion":-3},"news":"Bras de fer avec les Länder : le gouvernement mise sur sa lecture de la Loi fondamentale"}]},{"id":"allemagne-coalition-a-trois","title":"Querelle de coalition à trois","category":"politique","description":"Les trois partenaires de la coalition se disputent un budget : l'un veut taxer, l'autre épargner, le troisième planter des arbres. Le communiqué commun contient quatorze « toutefois ».","weight":5,"minTurn":2,"conditions":[{"gauge":"assemblee","op":"<","value":50}],"choices":[{"id":"compromis-nocturne","label":"Imposer un sommet de compromis nocturne","description":"Un accord à 4 h du matin, rédigé à l'encre fatiguée.","effects":{"assemblee":3,"budget":-3,"popularite":-1},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Chacun interprète l'accord à sa façon"}],"news":"Accord à 4 h du matin : la coalition tient jusqu'à midi"},{"id":"confiance","label":"Poser la question de confiance","description":"Demander aux députés de choisir entre l'unité et l'inconnu.","effects":{"assemblee":2,"popularite":-3,"international":-1},"news":"Question de confiance : le Chancelier mise sa place sur un mardi"},{"id":"laisser-couver","label":"Laisser les partenaires s'expliquer en public","description":"Observer, silencieux, les petites phrases s'accumuler.","effects":{"assemblee":-3,"popularite":-2,"cohesion":-1},"news":"Coalition : les petites phrases font les grands titres"}]},{"id":"allemagne-industrie-auto-tension","title":"L'industrie automobile tousse","category":"economie","description":"Un grand constructeur annonce la suppression de milliers de postes tout en félicitant ses équipes pour leur « agilité ». Les syndicats demandent à être associés, comme toujours, avec raison.","weight":5,"minTurn":3,"conditions":[{"gauge":"economie","op":"<","value":56}],"choices":[{"id":"aide-reconversion","label":"Plan de reconversion cofinancé","description":"Former les salariés vers l'électrique et le numérique.","effects":{"budget":-4,"economie":1,"cohesion":2,"popularite":1},"delayed":[{"delay":4,"effects":{"economie":1},"label":"Les anciens mécaniciens réparent des batteries"}],"news":"Plan de reconversion : le constructeur et l'État partagent l'addition"},{"id":"prime-achat","label":"Prime à l'achat de voitures électriques","description":"Subventionner la demande, en espérant que quelqu'un l'ait prévue.","effects":{"economie":2,"ecologie":1,"budget":-5,"popularite":1},"news":"Prime à l'électrique : les concessionnaires retrouvent le sourire"},{"id":"laisser-marche","label":"Laisser faire le marché","description":"Les mécanismes se corrigeront d'eux-mêmes, dit-on.","effects":{"budget":1,"economie":-3,"cohesion":-3,"popularite":-4},"news":"Industrie automobile : l'État s'en remet à la main invisible"}]},{"id":"allemagne-crue-du-fleuve","title":"Crue du grand fleuve","category":"climat","description":"Le niveau du grand fleuve monte de trois mètres et la navigation fluviale s'arrête. Les villages riverains rappellent qu'ils avaient demandé des digues, par écrit, en trois exemplaires.","weight":4,"minTurn":2,"choices":[{"id":"digues","label":"Financer un programme de digues","description":"Construire, enfin, ce qui avait été demandé.","effects":{"budget":-5,"ecologie":1,"securite":1,"popularite":1},"delayed":[{"delay":3,"effects":{"securite":1,"cohesion":1},"label":"Les digues tiennent l'hiver suivant"}],"news":"Programme de digues voté, les riverains demandent à voir les plans"},{"id":"indemniser","label":"Indemniser rapidement les sinistrés","description":"Un virement avant le séchage des tapis.","effects":{"budget":-4,"popularite":2,"cohesion":1},"news":"Indemnisation express : les sinistrés reçoivent un virement et du soutien"},{"id":"renaturer","label":"Rendre de la place au fleuve","description":"Reculer les habitations de plusieurs centaines de mètres.","effects":{"ecologie":3,"popularite":-3,"cohesion":-2,"budget":-2},"news":"Renaturation : le fleuve reprend ses droits, les maires reprennent leurs plaintes"}]},{"id":"allemagne-facture-energie-industrie","title":"La facture d'énergie des usines","category":"economie","description":"Les industriels chimiques menacent de déménager là où le courant coûte moins cher. Le patronat parle d'un « choc de compétitivité », le gouvernement d'un « moment important ».","weight":4,"minTurn":3,"conditions":[{"gauge":"economie","op":"<","value":58}],"choices":[{"id":"plafonner-prix","label":"Plafonner le prix de l'électricité industrielle","description":"Un tarif de crise, financé par la collectivité.","effects":{"economie":2,"budget":-5,"popularite":1,"ecologie":-1},"news":"Électricité plafonnée : les usines restent, la facture suit"},{"id":"accelerer-renouvelables","label":"Accélérer éoliennes et lignes à haute tension","description":"Produire plus, et plus près.","effects":{"ecologie":3,"economie":1,"budget":-3,"cohesion":-2},"delayed":[{"delay":4,"effects":{"economie":1,"ecologie":1},"label":"Le courant devient moins cher, enfin"}],"news":"Renouvelables en accéléré : les riverains découvrent les pylônes"},{"id":"delocaliser","label":"Laisser partir les procédés les plus gourmands","description":"S'adapter, comme on dit à l'étranger.","effects":{"economie":-3,"budget":1,"cohesion":-2,"popularite":-3},"news":"Industrie énergivore : le départ se fait « en bon ordre »"}]},{"id":"allemagne-fete-biere-record","title":"Fête de la bière : record de fréquentation","category":"economie","kind":"evenement","description":"La grande fête de la bière bat ses records de fréquentation, de chope et de chansons à boire. La balance commerciale n'ayant pas été consultée, le ministre se félicite tout de même.","weight":3,"conditions":[{"gauge":"popularite","op":">","value":45}],"choices":[{"id":"promo-tourisme","label":"Promouvoir le tourisme de fête","description":"Un spot publicitaire musical, avec accordéon.","effects":{"economie":2,"popularite":1,"budget":-2},"news":"Tourisme de fête : un accordéon national est commandé"},{"id":"securite-fete","label":"Renforcer le dispositif de sécurité","description":"Plus de personnel, plus de barrières, plus de fierté.","effects":{"securite":2,"budget":-2,"popularite":1},"news":"Fête de la bière : l'ordre règne, la mousse aussi"},{"id":"saluer-et-ranger","label":"Saluer l'événement et passer à autre chose","description":"Une photo, une chope, un sourire de circonstance.","effects":{"popularite":1,"cohesion":1},"news":"Le Chancelier lève sa chope, le reste attendra"}]}]`),r=[{id:"allemagne-frein-sous-controle",title:"Garder les comptes à l'équilibre",brief:"Un budget à 55 et les gardiens du frein à l'endettement vous enverront une carte de félicitations, en trois exemplaires.",objective:{type:"gaugeAtLeast",gauge:"budget",value:55},reward:{budget:2,assemblee:1},news:"Comptes : le frein tient, les ponts un peu moins"},{id:"allemagne-trains-ponctuels",title:"Faire avancer l'économie",brief:"Gagnez 4 points d'économie ce trimestre : le moteur allemand a le souffle court, mais les plans sont ponctuels.",objective:{type:"gaugeGain",gauge:"economie",value:4},reward:{economie:2,popularite:1},news:"Économie : le moteur reprend, discrètement, après vérification technique"},{id:"allemagne-laender-apaises",title:"Apaiser les Länder",brief:"Tenez la cohésion à 55 pour que seize gouvernements régionaux cessent de se plaindre à l'unisson.",objective:{type:"gaugeAtLeast",gauge:"cohesion",value:55},reward:{cohesion:2,assemblee:1},news:"Länder : la conférence des ministres-présidents se conclut par un communiqué commun"},{id:"allemagne-sans-jauge-rouge",title:"Un trimestre sans voyant rouge",brief:"Aucune jauge dans le rouge : un standard industriel que le pays applique en général aux machines.",objective:{type:"noRedGauge"},reward:{popularite:1,budget:1},news:"Aucune jauge dans le rouge : la machine tourne sans bruit suspect"}],l=JSON.parse('{"medias":["Der Rheinbote","Die Wochenwaage","Radio Kornblume","Spreewelle TV","Das Nordlicht"],"journalistes":[{"id":"allemagne-j-kuhnert","name":"Birgit Kuhnert-Salz","media":"Der Rheinbote","style":"pointilleuse : demande la source de la source de votre source","genre":"f"},{"id":"allemagne-j-tannenberg","name":"Florian Tannenberg","media":"Die Wochenwaage","style":"méthodique : pose une question en trois parties et exige trois réponses","genre":"m"},{"id":"allemagne-j-lindqvist","name":"Annelie Brandvoss","media":"Radio Kornblume","style":"chaleureuse : vous sourit pendant qu’elle vous coince","genre":"f"},{"id":"allemagne-j-hartmut","name":"Hartmut Bellinghausen","media":"Spreewelle TV","style":"impatient : vérifie sa montre plus souvent que ses notes","genre":"m"},{"id":"allemagne-j-sieglinde","name":"Sieglinde Morgenthau","media":"Das Nordlicht","style":"ironique : sait faire une pause qui coûte cher","genre":"f"},{"id":"allemagne-j-ottokar","name":"Ottokar Weidenfels","media":"Der Rheinbote","style":"nostalgique : compare tout à un budget d’il y a vingt ans","genre":"m"},{"id":"allemagne-j-marlene","name":"Marlene Eschenbach","media":"Die Wochenwaage","style":"tenace : revient sur votre réponse jusqu’à la fin du journal","genre":"f"}],"questions":[{"id":"allemagne-q-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef du gouvernement, votre cote de confiance descend plus vite qu’un train sans retard, c’est dire. Comptez-vous gouverner contre les sondages ou avec un baromètre plus indulgent ?","answers":[{"tone":"franche","label":"Le baromètre est honnête, et il ne me flatte pas. Je vais moins annoncer et plus livrer, en commençant par les ponts.","effects":{"popularite":5,"assemblee":-3},"news":"Le Chancelier reconnaît la baisse : « Moins d’annonces, plus de ponts »","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les partenaires de coalition prennent des notes"}]},{"tone":"langue-de-bois","label":"Un sondage n’est qu’un instantané. Je suis un processus, et un processus se juge à l’aune de son annexe finale.","effects":{"popularite":2,"international":-2},"news":"Le Chancelier se décrit comme « un processus » face aux sondages"},{"tone":"offensive","label":"Les baromètres mesurent l’humeur du matin. Moi, je gouverne pour le long terme, ce que les instituts ne savent pas encore chiffrer.","effects":{"popularite":5,"cohesion":-3,"assemblee":-2},"news":"Le Chancelier tacle les instituts : « Le long terme n’a pas de colonne »","delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les instituts publient un baromètre du baromètre"}]}]},{"id":"allemagne-q-industrie-faible","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Le Mittelstand s’inquiète : ces entreprises familiales qui exportent des machines dans le monde entier trouvent que le pays exporte surtout des formulaires. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"Ils ont raison. Je simplifie les procédures et j’accepte que certaines aides disparaissent pour financer des guichets numériques qui marchent.","effects":{"economie":5,"budget":-3},"news":"Le Chancelier promet aux PME des guichets numériques « qui marchent »","delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les fonctionnaires redoutent la fin du papier"}]},{"tone":"langue-de-bois","label":"L’industrie est notre colonne vertébrale. Nous la soutiendrons, la renforcerons et, le cas échéant, la consulterons.","effects":{"economie":2,"popularite":-2},"news":"Le Chancelier veut « consulter la colonne vertébrale »"},{"tone":"offensive","label":"Quand les concurrents subventionnent leurs usines, je réponds par des baisses d’impôts massives. Que ceux qui critiquent le déficit viennent le financer.","effects":{"economie":6,"budget":-4,"international":-2},"news":"Le Chancelier lance un grand plan fiscal pour les usines","delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les Verts dénoncent un cadeau aux cheminées"}]}]},{"id":"allemagne-q-frein-dette-ponts","theme":"budget","condition":{"gauge":"budget","op":"<","value":40},"text":"Chef du gouvernement, le frein à l’endettement est sacré, mais le pont de l’autoroute régionale, lui, est limité à 3,5 tonnes depuis neuf ans. Qui l’emportera, la règle ou le pont ?","answers":[{"tone":"franche","label":"Le pont, et sans honte. J’assouplis le frein pour l’investissement utile, mais chaque euro sera tracé, annexé et vérifié trois fois.","effects":{"international":3,"budget":-4,"assemblee":-2},"news":"Le Chancelier assouplit le frein pour sauver un pont","delayed":[{"delay":2,"effects":{"economie":3},"label":"Les entreprises de travaux publics sortent les casques"}]},{"tone":"langue-de-bois","label":"Le frein est un principe, le pont est une réalité, et entre les deux nous poursuivons un dialogue constructif de long terme.","effects":{"budget":2,"popularite":-2},"news":"Entre le frein et le pont, le Chancelier choisit le « dialogue »"},{"tone":"offensive","label":"Ceux qui veulent la rigueur absolue peuvent traverser ce pont à pied, avec leur calculette. Moi, je répare, et je présente la facture après.","effects":{"popularite":5,"economie":3,"budget":-5},"news":"Le Chancelier aux rigoristes : « Traversez à pied »","delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Les libéraux saisissent le tribunal constitutionnel de leur calculette"}]}]},{"id":"allemagne-q-loyers-courses","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":45},"text":"Dans les grandes villes, on fait la queue pour visiter un deux-pièces comme on la faisait pour des places de concert. Que dites-vous à ceux qui consacrent la moitié de leur salaire au loyer ?","answers":[{"tone":"franche","label":"Que j’ai trop attendu. Je facilite la construction, je plafonne les hausses les plus absurdes, et je sais que les deux camps m’en voudront.","effects":{"pouvoirAchat":5,"economie":-3},"news":"Logement : le Chancelier promet de construire et de plafonner","delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les propriétaires et les locataires s’indignent en chœur"}]},{"tone":"langue-de-bois","label":"Le logement est un sujet transversal, pluriel et multidimensionnel que nous aborderons avec une méthode à plusieurs niveaux.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Logement : une méthode « à plusieurs niveaux », sans étage de plus"},{"tone":"offensive","label":"Les spéculateurs ont dix jours pour proposer des appartements abordables, sinon ce sont des hangars qu’on leur construira à côté.","effects":{"pouvoirAchat":6,"popularite":3,"economie":-4},"news":"Le Chancelier somme les spéculateurs de proposer des loyers abordables","delayed":[{"delay":2,"effects":{"international":-2},"label":"Des investisseurs étrangers reportent leurs visites"}]}]},{"id":"allemagne-q-cyber-polices","theme":"securite","condition":{"gauge":"securite","op":"<","value":45},"text":"La police relève des seize Länder, le renseignement du niveau fédéral, et les pirates, eux, n’ont aucune compétence territoriale. Vous sentez-vous en sécurité avec un organigramme pareil ?","answers":[{"tone":"franche","label":"Non, et c’est le prix du fédéralisme. Je propose un centre commun de cybersécurité, quitte à froisser quelques ministres régionaux.","effects":{"securite":5,"cohesion":-3},"news":"Cybersécurité : le Chancelier veut un centre commun aux seize Länder","delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les ministres régionaux réclament un siège chacun"}]},{"tone":"langue-de-bois","label":"Notre architecture de sécurité est robuste, résiliente et coordonnée, y compris lorsqu’elle ne l’est pas encore.","effects":{"securite":2,"popularite":-2},"news":"Le Chancelier juge l’architecture de sécurité « coordonnée, même quand elle ne l’est pas »"},{"tone":"offensive","label":"Les pirates ont intérêt à revoir leur calendrier, car j’ai augmenté les moyens des enquêteurs et lancé un ultimatum aux administrations qui utilisent encore des mots de passe sur papier.","effects":{"securite":6,"popularite":2,"budget":-4},"news":"Cyber : le Chancelier menace les mots de passe sur papier","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les fonctionnaires jugent le ton « sans préavis écrit »"}]}]},{"id":"allemagne-q-est-ouest","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":40},"text":"Plusieurs décennies après la réunification, on note des différences de salaires, de trains et de réseau mobile entre l’est et l’ouest. Comment recoudre ce qui ne l’est pas tout à fait ?","answers":[{"tone":"franche","label":"En reconnaissant que l’égalité a pris du retard, et en priorisant les liaisons ferroviaires, la fibre et les emplois dans l’est, quitte à me faire reprocher des préférences.","effects":{"cohesion":5,"budget":-3,"assemblee":-2},"news":"Le Chancelier veut rattraper l’est : trains, fibre et emplois","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les villes de l’est voient enfin passer un chantier"}]},{"tone":"langue-de-bois","label":"L’unité est un chemin, pas une destination, et nous marchons ensemble, à des allures différentes mais complémentaires.","effects":{"cohesion":2,"popularite":-2},"news":"Le Chancelier : « Nous marchons à des allures complémentaires »"},{"tone":"offensive","label":"Les nostalgiques de tout bord peuvent se plaindre, moi je construis. Que ceux qui divisent proposent un horaire de train ou taisent leurs sifflets.","effects":{"popularite":4,"assemblee":-3,"cohesion":-3},"news":"Le Chancelier aux divisions : « Proposez un horaire »","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"L’opposition de droite radicale se dit offusquée à haute voix"}]}]},{"id":"allemagne-q-charbon-ecologie","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":40},"text":"Les mines de charbon ferment et les éoliennes se multiplient, mais les villes minières demandent ce qu’elles feront de leurs terrils. Peut-on tourner la page sans tourner le dos ?","answers":[{"tone":"franche","label":"Il faut accélérer la sortie du charbon et financer sérieusement la reconversion. Je préfère être jugé sur des emplois créés que sur des promesses recyclées.","effects":{"ecologie":5,"economie":-3,"cohesion":-2},"news":"Charbon : le Chancelier accélère la sortie et finance la reconversion","delayed":[{"delay":3,"effects":{"budget":-2},"label":"La facture de la reconversion s’invite au budget"}]},{"tone":"langue-de-bois","label":"La transition sera juste, durable et inclusive, avec un calendrier flexible, ambitieux et, surtout, révisable.","effects":{"ecologie":2,"economie":-2},"news":"Charbon : un calendrier « ambitieux et surtout révisable »"},{"tone":"offensive","label":"Ceux qui crient qu’on tue l’industrie par la transition oublient que les terrils fleurissent mieux sous des panneaux solaires. Le climat n’attend pas leur nostalgie.","effects":{"ecologie":6,"popularite":3,"cohesion":-4},"news":"Le Chancelier : « Les terrils fleurissent mieux sous des panneaux »","delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les élus des régions minières claquent la porte du comité"}]}]},{"id":"allemagne-q-locomotive-europe","theme":"international","condition":{"gauge":"international","op":">","value":65},"text":"Votre pays est la locomotive économique du continent, mais ses voisins aimeraient que la locomotive s’arrête plus souvent dans leurs gares. Quel rôle voulez-vous jouer en Europe ?","answers":[{"tone":"franche","label":"Celui d’un partenaire qui paie sa part et assume de diriger quand il le faut. La confiance se mérite, mais elle se finance aussi.","effects":{"international":4,"budget":-4},"news":"Europe : le Chancelier assume la part du « payeur et du pilote »","delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Une partie de l’opinion se demande qui paiera le carburant"}]},{"tone":"langue-de-bois","label":"L’Europe est notre horizon commun, notre projet partagé et notre destin collectif, sous réserve d’un examen approfondi des détails.","effects":{"international":2,"economie":-2},"news":"L’Europe, « horizon commun, sous réserve d’examen »"},{"tone":"offensive","label":"Ceux qui nous reprochent de dominer feraient mieux de proposer des trains qui arrivent à l’heure. Nous avançons, qu’ils nous suivent ou qu’ils prennent le bus.","effects":{"popularite":4,"international":-5,"assemblee":-2},"news":"Le Chancelier : « Suivez-nous, ou prenez le bus »","delayed":[{"delay":2,"effects":{"international":-2},"label":"Les capitales voisines convoquent des réunions de crise… polies"}]}]},{"id":"allemagne-q-bundestag-fragile","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":40},"text":"Votre coalition vote en ordre dispersé : trois partis, quatre avis, et au moins cinq annexes à l’accord. Combien de jours tient encore votre majorité au Bundestag ?","answers":[{"tone":"franche","label":"Autant qu’il y aura de compromis acceptables, et je m’y emploie. Si je dois lâcher un projet cher à l’un des partenaires pour sauver l’ensemble, je le ferai.","effects":{"assemblee":5,"popularite":-3},"news":"Le Chancelier : « Je lâcherai un projet pour sauver l’ensemble »","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Un partenaire de coalition boude, poliment"}]},{"tone":"langue-de-bois","label":"La coalition est solide, soudée et constructive. Les désaccords qui s’expriment sont la preuve d’une vitalité démocratique.","effects":{"assemblee":2,"popularite":-2},"news":"Le Chancelier voit dans les disputes de coalition « une vitalité »"},{"tone":"offensive","label":"Les députés qui hésitent sont libres de voter contre, mais ils devront l’expliquer dans leur circonscription, au marché, devant les saucisses.","effects":{"assemblee":6,"popularite":2,"cohesion":-4},"news":"Le Chancelier aux hésitants : « Expliquez-le devant les saucisses »","delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Le groupe parlementaire se plaint d’avoir été « saucissonné »"}]}]},{"id":"allemagne-q-excedent-export","theme":"economie","condition":{"gauge":"economie","op":">","value":70},"text":"Les exportations battent des records et l’excédent commercial gonfle. Certains partenaires protestent que vous vendez beaucoup et n’achetez pas assez. Pourquoi ne pas dépenser ce que vous gagnez ?","answers":[{"tone":"franche","label":"Parce que nous avons des habitudes d’épargne, mais ils n’ont pas tout à fait tort. Je lance un plan d’investissement pour les routes, les écoles et les réseaux.","effects":{"international":4,"budget":-4,"economie":-2},"news":"Excédent : le Chancelier promet d’investir plutôt que d’empiler","delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les chantiers de proximité commencent à recruter"}]},{"tone":"langue-de-bois","label":"Un excédent est le fruit d’efforts collectifs, d’une compétitivité structurelle et d’une certaine rigueur. Nous l’analyserons avec nos partenaires.","effects":{"economie":2,"international":-2},"news":"Excédent commercial : le Chancelier promet une « analyse »"},{"tone":"offensive","label":"Les critiques voudraient que nous vendions moins bien. Nous vendons des machines que le monde réclame ; qu’ils fassent donc de meilleures machines.","effects":{"economie":5,"popularite":2,"international":-5},"news":"Le Chancelier aux critiques : « Faites de meilleures machines »","delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les prix à l’import deviennent un sujet de dîner"}]}]},{"id":"allemagne-q-excedent-budget","theme":"budget","condition":{"gauge":"budget","op":">","value":70},"text":"Les caisses sont pleines, ce qui est d’habitude un problème que les pays aimeraient avoir. Pourtant, les écoles ont des toits qui fuient et les ponts perdent des morceaux. Est-ce le moment de dépenser ?","answers":[{"tone":"franche","label":"Oui, avec méthode. Une bonne gestion ne consiste pas à garder l’argent sous un matelas mais à réparer ce qui va nous coûter plus cher demain.","effects":{"popularite":4,"budget":-4},"news":"Le Chancelier : « L’argent n’est pas fait pour dormir sous un matelas »","delayed":[{"delay":3,"effects":{"economie":2},"label":"Les entreprises du bâtiment sortent leurs plans"}]},{"tone":"langue-de-bois","label":"Notre priorité demeure l’équilibre, la soutenabilité et la prudence, tout en gardant à l’esprit la nécessité d’investir de façon raisonnable.","effects":{"budget":2,"popularite":-2},"news":"Le Chancelier veut investir « de façon raisonnable, prudente et équilibrée »"},{"tone":"offensive","label":"Les caisses sont pleines parce que nous les avons bien tenues. Que ceux qui veulent les vider y réfléchissent à deux fois, et en lisent les tableaux.","effects":{"budget":5,"assemblee":2,"popularite":-4},"news":"Le Chancelier défend les caisses pleines contre les dépensiers","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les écoles organisent une collecte pour les toits"}]}]},{"id":"allemagne-q-popularite-haute","theme":"popularite","condition":{"gauge":"popularite","op":">","value":70},"text":"Les sondages vous sont favorables, mais les chefs de gouvernement savent combien dure la lune de miel : environ le temps d’un congé de printemps. Quel est votre secret ?","answers":[{"tone":"franche","label":"Aucun secret : j’ai écouté, j’ai corrigé et j’ai évité de promettre le ciel. Mais je sais que la confiance se perd plus vite qu’elle ne se gagne.","effects":{"cohesion":4,"assemblee":-2},"news":"Popularité : le Chancelier prévient que « la confiance se perd vite »","delayed":[{"delay":3,"effects":{"popularite":2},"label":"L’opinion apprécie cette modestie rare"}]},{"tone":"langue-de-bois","label":"La confiance des citoyens m’honore, m’oblige et m’engage à poursuivre un travail de fond dans la continuité et le dialogue.","effects":{"popularite":2,"economie":-2},"news":"Le Chancelier remercie les sondages d’un long communiqué"},{"tone":"offensive","label":"Mon secret, c’est que l’opposition a la mémoire courte et des tracts longs. Plus ils crient, plus le public regarde les chiffres.","effects":{"popularite":4,"assemblee":-3,"cohesion":-3},"news":"Le Chancelier aux opposants : « Regardez les chiffres »","delayed":[{"delay":2,"effects":{"international":-2},"label":"La presse étrangère parle d’un excès de confiance"}]}]},{"id":"allemagne-q-eoliennes-paysage","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":70},"text":"Les éoliennes sont devenues les nouveaux clochers des villages. Certains les aiment, d’autres demandent qu’on les déplace derrière les nuages. Allez-vous en planter davantage ?","answers":[{"tone":"franche","label":"Oui, mais avec des communes qui y gagnent, par des loyers et des tarifs d’électricité plus bas. Un moulin à vent qui rapporte est un moulin mieux accepté.","effects":{"ecologie":4,"pouvoirAchat":2,"budget":-3},"news":"Éoliennes : le Chancelier veut que les communes en profitent","delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les maires voisins demandent un moulin chacun"}]},{"tone":"langue-de-bois","label":"Le paysage est un patrimoine vivant, évolutif et partagé, que nous concilierons avec les impératifs de la transition énergétique.","effects":{"ecologie":2,"popularite":-2},"news":"Le paysage, « patrimoine vivant et partagé », selon le Chancelier"},{"tone":"offensive","label":"Ceux qui s’opposent à l’éolien préfèrent sans doute la fumée à la vue. Je préfère un horizon avec des pales à un horizon avec des cheminées.","effects":{"ecologie":6,"popularite":2,"cohesion":-4},"news":"Le Chancelier : « Je préfère des pales aux cheminées »","delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Un groupe de défense des paysages porte plainte… dans un champ"}]}]},{"id":"allemagne-q-panier-aise","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":">","value":70},"text":"Le panier de la ménagère est plutôt garni et les salaires suivent. Les syndicats demandent pourtant leur part du gâteau, et le gâteau est prévu pour cinq cents personnes. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"Qu’une part est due, mais pas le gâteau entier. Je plaide pour des hausses liées à la productivité, discutées à la table de la cogestion.","effects":{"cohesion":4,"economie":-3},"news":"Salaires : le Chancelier veut une part de gâteau, pas le gâteau entier","delayed":[{"delay":3,"effects":{"pouvoirAchat":-2},"label":"Les prix du café et des gâteaux font un petit bond"}]},{"tone":"langue-de-bois","label":"Le dialogue social est une valeur fondamentale. Nous continuerons à le faire vivre dans un cadre responsable, équilibré et équitable.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Salaires : le Chancelier cite trois fois le « dialogue social »"},{"tone":"offensive","label":"Les syndicats veulent le gâteau et la bougie. Je leur propose un ruban de bonne conduite et une feuille de route, et nous mangerons ensuite.","effects":{"economie":5,"budget":2,"cohesion":-5},"news":"Le Chancelier propose « un ruban de bonne conduite » aux syndicats","delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les syndicats organisent un pique-nique revendicatif"}]}]},{"id":"allemagne-q-frontieres-controles","theme":"securite","text":"On a rétabli des contrôles à certaines frontières, ce qui fait râler les pendulaires, les commerçants et les voisins. Les frontières ouvertes sont-elles un luxe d’un autre temps ?","answers":[{"tone":"franche","label":"Non, mais la sécurité est une condition. Les contrôles resteront ciblés et temporaires, pendant que nous coordonnons mieux avec nos voisins.","effects":{"securite":5,"international":-3},"news":"Frontières : des contrôles « ciblés et temporaires », promet le Chancelier","delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les pendulaires acceptent de patienter, café en main"}]},{"tone":"langue-de-bois","label":"Nous restons attachés à l’espace de libre circulation, tout en veillant, avec la plus grande vigilance, à ce que sa liberté soit parfaitement encadrée.","effects":{"securite":2,"popularite":-2},"news":"Le Chancelier veut une liberté « parfaitement encadrée »"},{"tone":"offensive","label":"Ceux qui dénoncent ces contrôles proposent une solution sérieuse ou se contentent de faire la queue ? Je choisis la sécurité des citoyens.","effects":{"securite":6,"popularite":3,"international":-4,"cohesion":-2},"news":"Le Chancelier aux critiques des contrôles : « Avez-vous une solution ? »","delayed":[{"delay":3,"effects":{"economie":-2},"label":"Les camions font la queue plus longtemps que les débats"}]}]},{"id":"allemagne-q-laender-richesse","theme":"cohesion","text":"Les Länder riches paient pour les plus modestes, ce qui donne lieu à des échanges musclés dans les salles de réunion. Faut-il revoir la répartition, ou seulement le café ?","answers":[{"tone":"franche","label":"La solidarité fédérale est un pilier, mais elle doit rester lisible. Je propose une réforme transparente, avec des critères que chacun peut vérifier.","effects":{"cohesion":5,"assemblee":-3},"news":"Péréquation : le Chancelier promet des critères que chacun peut vérifier","delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Trois ministres-présidents exigent un tableau de plus"}]},{"tone":"langue-de-bois","label":"L’équilibre des territoires est un défi permanent que nous relevons en concertation étroite avec l’ensemble des partenaires concernés.","effects":{"cohesion":2,"popularite":-2},"news":"Péréquation : « concertation étroite » avec tous les partenaires"},{"tone":"offensive","label":"Que les Länder qui réclament plus montrent d’abord leurs budgets, et nous verrons ensuite si le café suffit.","effects":{"assemblee":3,"budget":3,"cohesion":-5},"news":"Le Chancelier aux Länder : « Montrez vos budgets d’abord »","delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les régions du sud et du nord s’accusent en dialecte"}]}]},{"id":"allemagne-q-frein-dette-blocage","theme":"crise","crisisId":"allemagne-frein-dette-blocage","text":"Le frein à l’endettement bloque tout, depuis les routes jusqu’aux budgets d’école. Vos ministres se disputent pour savoir qui a oublié de remplir quelle annexe. Qui pilote vraiment ?","answers":[{"tone":"franche","label":"Je pilote, et j’assume que le frein ait été mal compris. Nous allons trier les dépenses essentielles et expliquer chaque choix à la population.","effects":{"popularite":4,"budget":-3,"assemblee":-2},"news":"Frein à la dette : le Chancelier prend la barre","delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les ministres se réconcilient autour d’un tableau"}]},{"tone":"langue-de-bois","label":"La situation budgétaire est sous contrôle, et nous menons un examen approfondi de toutes les options dans le respect du cadre constitutionnel.","effects":{"budget":2,"assemblee":-3},"news":"Le Chancelier lance un « examen approfondi de toutes les options »"},{"tone":"offensive","label":"Ceux qui crient au blocage n’ont qu’à signer leurs propres annexes. Moi, je gouverne, et les formulaires suivront.","effects":{"assemblee":4,"popularite":2,"cohesion":-4},"news":"Le Chancelier : « Je gouverne, les formulaires suivront »","delayed":[{"delay":3,"effects":{"international":-3},"label":"Les agences de notation envoient un courriel poli mais ferme"}]}]},{"id":"allemagne-q-trains-8h12","theme":"crise","crisisId":"allemagne-trains-en-retard","text":"Le train de 8 h 12 doit arriver demain, a-t-on annoncé dans une gare. Dans un pays qui prétend à la précision, comment expliquez-vous ce rapport si tendu avec l’heure ?","answers":[{"tone":"franche","label":"Nous avons sous-investi dans le rail pendant trop longtemps. Je lance un plan de ponctualité avec un budget pluriannuel et des indicateurs publics.","effects":{"popularite":4,"securite":2,"budget":-5},"news":"Rail : le Chancelier lance un plan de ponctualité à indicateurs publics","delayed":[{"delay":3,"effects":{"economie":2},"label":"Les voyageurs saluent, quelques minutes en retard"}]},{"tone":"langue-de-bois","label":"La mobilité est un enjeu structurant, multimodal et interconnecté, et nous garantissons un service plus fiable dans les meilleurs délais.","effects":{"popularite":2,"economie":-2},"news":"Rail : « un service plus fiable dans les meilleurs délais »"},{"tone":"offensive","label":"Ce retard est celui de vingt ans de gestion que je ne partage pas. Je somme la compagnie ferroviaire de présenter ses horaires, ou ses excuses.","effects":{"popularite":5,"budget":2,"cohesion":-4},"news":"Le Chancelier somme le Rail de présenter horaires ou excuses","delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les syndicats de cheminots répondent par un préavis… ponctuel"}]}]},{"id":"allemagne-q-lander-bundesrat","theme":"crise","crisisId":"allemagne-lander-bras-de-fer","text":"Les Länder bloquent votre texte au Bundesrat, chacun défendant sa spécialité locale, sa carte de rails et sa bière. Allez-vous négocier région par région, ou construire une grande salle de réunion ?","answers":[{"tone":"franche","label":"Je négocie, région par région, en acceptant des concessions réelles. Un compromis imparfait vaut mieux qu’un texte parfait qui n’est jamais appliqué.","effects":{"assemblee":5,"budget":-3},"news":"Bundesrat : le Chancelier négocie région par région","delayed":[{"delay":3,"effects":{"cohesion":3},"label":"Les régions apprécient d’être consultées, pour une fois"}]},{"tone":"langue-de-bois","label":"Le Bundesrat est le lieu naturel du dialogue fédéral, où chacun exprime sa sensibilité territoriale dans un esprit de coresponsabilité.","effects":{"assemblee":2,"popularite":-2},"news":"Le Chancelier salue la « coresponsabilité » du Bundesrat"},{"tone":"offensive","label":"Les Länder qui bloquent feront-ils aussi la queue pour réclamer des fonds fédéraux ? Je leur propose de choisir entre leur veto et leur subvention.","effects":{"assemblee":6,"budget":3,"cohesion":-5},"news":"Le Chancelier aux Länder : « Veto ou subvention, choisissez »","delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Trois ministres-présidents boycottent le dîner de gala"}]}]},{"id":"allemagne-q-coalition-trois","theme":"crise","crisisId":"allemagne-coalition-a-trois","text":"Les trois partis de la coalition s’opposent sur un projet : l’un veut des baisses d’impôts, l’autre des dépenses sociales, le troisième des panneaux solaires sur le Bundestag. Lequel faut-il écouter ?","answers":[{"tone":"franche","label":"Les trois, et c’est précisément le problème. Je vais imposer un calendrier de décisions, avec un arbitrage public si le consensus échoue.","effects":{"assemblee":4,"popularite":-3},"news":"Coalition : le Chancelier impose un calendrier d’arbitrage","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Un partenaire se plaint d’avoir été « arbitré »"}]},{"tone":"langue-de-bois","label":"La coalition est un espace de dialogue fécond. Les divergences se résorbent dans l’intérêt supérieur d’un accord de coalition complet et équilibré.","effects":{"assemblee":2,"popularite":-2},"news":"Coalition : le Chancelier invoque « l’intérêt supérieur de l’accord »"},{"tone":"offensive","label":"Quand trois partis se disputent, c’est que le pays compte trois idées. Je choisis la quatrième : la mienne, et elle est déjà budgétée.","effects":{"popularite":5,"assemblee":-4,"cohesion":-3},"news":"Le Chancelier : « Je choisis la quatrième idée : la mienne »","delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les trois partenaires se découvrent une solidarité inattendue… contre lui"}]}]},{"id":"allemagne-q-auto-industrie","theme":"crise","crisisId":"allemagne-industrie-auto-tension","text":"L’industrie automobile, fleuron du pays, tousse : les moteurs électriques arrivent, les contremaîtres s’inquiètent et les concurrents étrangers roulent plus vite. Quelle est votre feuille de route ?","answers":[{"tone":"franche","label":"Accompagner la transition sans mentir : certains postes disparaîtront, d’autres naîtront, et l’État financera la formation des salariés concernés.","effects":{"cohesion":4,"economie":2,"budget":-5},"news":"Automobile : le Chancelier promet la formation sans mensonge","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les salariés saluent un discours qui ne sent pas le vernis"}]},{"tone":"langue-de-bois","label":"L’automobile est un fleuron industriel, un savoir-faire et un patrimoine que nous accompagnerons dans toutes ses mutations technologiques.","effects":{"economie":2,"ecologie":-2},"news":"Automobile : « accompagner toutes les mutations », sans en nommer aucune"},{"tone":"offensive","label":"Si les constructeurs veulent une subvention, qu’ils s’engagent à produire ici et à embaucher ici. Pas de chèque sans plan, pas de plan sans ouvriers.","effects":{"popularite":4,"economie":3,"international":-3,"budget":-3},"news":"Le Chancelier aux constructeurs : « Pas de chèque sans plan »","delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Un grand constructeur menace de déménager ses boulons"}]}]},{"id":"allemagne-q-energie-usines","theme":"crise","crisisId":"allemagne-facture-energie-industrie","text":"La facture d’énergie des usines grimpe plus vite que la température des fours. Les patrons parlent de délocalisation et les syndicats de solidarité. Avez-vous un plan, ou seulement une calculette ?","answers":[{"tone":"franche","label":"J’ai un plan, qui coûte cher : réseaux, stockage et un tarif transitoire pour les industries les plus exposées. Personne n’aime l’addition, mais elle est honnête.","effects":{"economie":5,"ecologie":2,"budget":-5},"news":"Énergie : un tarif transitoire pour les usines, annonce le Chancelier","delayed":[{"delay":3,"effects":{"pouvoirAchat":-2},"label":"Les ménages découvrent leur part de l’addition"}]},{"tone":"langue-de-bois","label":"L’énergie est un enjeu de souveraineté, de compétitivité et de solidarité, que nous abordons avec une vision globale, intégrée et pragmatique.","effects":{"economie":2,"popularite":-2},"news":"Énergie : le Chancelier a une « vision globale, intégrée et pragmatique »"},{"tone":"offensive","label":"Ceux qui pleurent sur leur facture auraient dû investir dans l’efficacité. Je ne financerai pas les fours qui chauffent le jardin.","effects":{"budget":4,"ecologie":2,"economie":-4,"popularite":-2},"news":"Énergie : « Pas d’argent pour les fours qui chauffent le jardin »","delayed":[{"delay":2,"effects":{"cohesion":-3},"label":"Les syndicats parlent de « chauffage par le bas »"}]}]},{"id":"allemagne-q-fete-biere","theme":"crise","crisisId":"allemagne-fete-biere-record","text":"La grande fête de la bière bat un record de fréquentation et d’écume, avec les services d’urgence qui comptent les chopes et les chaises cassées. Que dit le chef du gouvernement à ses citoyens ?","answers":[{"tone":"franche","label":"Que la fête est une tradition que nous aimons, mais que la sécurité et le tri des verres comptent aussi. Je lèverai le mien en respectant les règles.","effects":{"securite":4,"popularite":2,"economie":-3},"news":"Fête de la bière : le Chancelier trinque, mais surveille les verres","delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les brasseurs offrent une tournée de rattrapage"}]},{"tone":"langue-de-bois","label":"Cet événement est un rendez-vous festif, populaire et patrimonial, qui reflète notre attachement collectif au vivre-ensemble.","effects":{"popularite":2,"securite":-2},"news":"Fête de la bière : « un attachement collectif au vivre-ensemble »"},{"tone":"offensive","label":"Quelqu’un a-t-il déjà reproché à une mousse d’être dans le budget ? Je préfère la fête à ceux qui font le décompte de la mousse.","effects":{"popularite":5,"cohesion":2,"securite":-3,"budget":-3},"news":"Le Chancelier défend la mousse contre les comptables","delayed":[{"delay":3,"effects":{"ecologie":-2},"label":"Les camions de bouteilles ont leur propre bouchon"}]}]},{"id":"allemagne-q-niveau-fleuve","theme":"crise","text":"Après la crue vient la sécheresse : le grand fleuve est si bas que les péniches s’y promènent à pied. Que ferez-vous pour le transport, l’agriculture et les paysages bleus de votre tableau de bord ?","answers":[{"tone":"franche","label":"Il nous faut des stocks d’eau, des cultures moins gourmandes et un transport plus varié. Ce sera long, coûteux et nécessaire.","effects":{"ecologie":5,"economie":-2,"budget":-4},"news":"Fleuve trop bas : le Chancelier prépare un plan eau","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les agriculteurs saluent un plan qui ne tombe pas du ciel"}]},{"tone":"langue-de-bois","label":"La gestion de la ressource en eau est un chantier transversal qui exige une approche coordonnée, des solutions innovantes et un sens aigu de la responsabilité.","effects":{"ecologie":2,"popularite":-2},"news":"Le fleuve baisse, la « responsabilité » monte"},{"tone":"offensive","label":"Les pessimistes voient un fleuve vide ; je vois des quais plus faciles à nettoyer. Que ceux qui veulent des solutions miracles se présentent avec un seau.","effects":{"popularite":4,"ecologie":-3,"cohesion":-3},"news":"Le Chancelier : « Les quais sont plus faciles à nettoyer »","delayed":[{"delay":2,"effects":{"economie":-3},"label":"Les armateurs envoient la facture des péniches échouées"}]}]},{"id":"allemagne-q-affaire-avion","theme":"scandale","text":"On apprend qu’un de vos ministres a utilisé l’avion de la flotte fédérale pour aller inaugurer un four à pain dans sa circonscription. Il parle d’un déplacement « à haute valeur symbolique ». Qu’en pensez-vous ?","answers":[{"tone":"franche","label":"Que c’est une erreur. Il remboursera le trajet et présentera ses excuses. Le pain peut être cuit au sol, l’avion est réservé aux affaires du pays.","effects":{"popularite":4,"assemblee":-3},"news":"Avion et four à pain : le Chancelier exige un remboursement","delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Le ministre promet de prendre le train, s’il arrive"}]},{"tone":"langue-de-bois","label":"Les déplacements ministériels obéissent à des règles précises que nous examinerons avec la plus grande transparence, au moment opportun.","effects":{"popularite":2,"assemblee":-2},"news":"Affaire de l’avion : « examen transparent, au moment opportun »"},{"tone":"offensive","label":"Un four à pain inauguré, c’est un électeur de plus. Certains critiquent un trajet ; moi je salue un ministre qui s’occupe du terrain. Au moins, il décolle.","effects":{"assemblee":4,"popularite":-4,"international":-2},"news":"Le Chancelier défend son ministre : « Au moins, il décolle »","delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Une pétition réclame un avion pour chaque four à pain"}]}]},{"id":"allemagne-q-affaire-lobby","theme":"scandale","text":"Un document fuité suggère qu’un lobby de fabricants de saucisses a rédigé une partie d’une directive sur l’étiquetage. L’opposition parle de « charcuterie politique ». Que répondez-vous ?","answers":[{"tone":"franche","label":"Je demande la publication des échanges et la révision de la directive. Si un lobby a tenu le stylo, je veux savoir lequel, et de quelle marque.","effects":{"popularite":4,"economie":-3},"news":"Affaire des saucisses : le Chancelier ordonne la transparence","delayed":[{"delay":3,"effects":{"assemblee":2},"label":"Le Bundestag adopte un registre des lobbies"}]},{"tone":"langue-de-bois","label":"La consultation des parties prenantes est une pratique normale, encadrée et fructueuse, indispensable à l’élaboration de textes équilibrés.","effects":{"assemblee":2,"popularite":-3},"news":"Le Chancelier défend « une pratique normale, encadrée et fructueuse »"},{"tone":"offensive","label":"Les mêmes qui dénoncent le lobby des saucisses ont déjeuné chez celui des légumes. La transparence, c’est pour tout le buffet.","effects":{"popularite":3,"assemblee":-4,"cohesion":-2},"news":"Le Chancelier à l’opposition : « La transparence vaut pour tout le buffet »","delayed":[{"delay":2,"effects":{"international":-2},"label":"La presse étrangère dissèque le menu des lobbies"}]}]},{"id":"allemagne-q-affaire-cabinet","theme":"scandale","text":"Le cabinet d’un secrétaire d’État a embauché trois cousins et un voisin pour une étude sur l’efficacité administrative. Le rapport, lui, compte quarante pages de graphiques en forme de saucisse. Un commentaire ?","answers":[{"tone":"franche","label":"C’est indéfendable. J’ai demandé l’annulation du contrat et le remboursement des sommes. L’efficacité administrative commence par l’honnêteté.","effects":{"popularite":5,"assemblee":-3,"cohesion":-2},"news":"Cabinet et cousins : le Chancelier annule le contrat","delayed":[{"delay":2,"effects":{"budget":2},"label":"Les sommes sont restituées, avec un reçu"}]},{"tone":"langue-de-bois","label":"Une enquête interne a été diligentée afin de faire toute la lumière dans le respect des procédures et des délais réglementaires.","effects":{"assemblee":2,"popularite":-3},"news":"Cabinet et cousins : une enquête interne « dans les délais réglementaires »"},{"tone":"offensive","label":"Quarante pages de graphiques valent mieux que quarante pages de procès d’intention. Que ceux qui ont des cousins sans emploi me jettent la première annexe.","effects":{"assemblee":3,"popularite":-4,"international":-3},"news":"Le Chancelier ironise sur les cousins sans emploi de ses critiques","delayed":[{"delay":3,"effects":{"cohesion":-3},"label":"Le registre des cousins devient un sujet de débat"}]}]},{"id":"allemagne-q-ponctualite-culture","theme":"popularite","text":"Le pays est réputé pour sa ponctualité, mais aussi pour ses règles qui interdisent de tondre la pelouse le dimanche. Quelle règle absurde aimeriez-vous supprimer, et quelle règle ridicule défendriez-vous ?","answers":[{"tone":"franche","label":"Je supprimerais les formulaires en triple exemplaire et je défendrais le repos du dimanche. Un pays qui se tait un jour par semaine se porte mieux.","effects":{"popularite":4,"economie":-2},"news":"Le Chancelier défend le dimanche et attaque les triples exemplaires","delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les voisins lui offrent une tondeuse silencieuse"}]},{"tone":"langue-de-bois","label":"Chaque règle a été pensée avec un souci de cohérence, d’équilibre et d’harmonie, et nous veillons à la faire évoluer en concertation.","effects":{"popularite":2,"economie":-2},"news":"Règles absurdes : le Chancelier voit de l’« harmonie » partout"},{"tone":"offensive","label":"La règle absurde, c’est celle qui retarde mes réformes. La règle respectable, c’est celle qui protège ma sieste. Que mes critiques tondent leur gazon un mardi.","effects":{"popularite":5,"assemblee":-3,"cohesion":-2},"news":"Le Chancelier : « Que mes critiques tondent leur gazon un mardi »","delayed":[{"delay":3,"effects":{"international":-2},"label":"Un magazine étranger publie un dossier sur ses habitudes de sieste"}]}]},{"id":"allemagne-q-football-selection","theme":"cohesion","text":"La sélection nationale de football est battue par un pays plus petit, et les cafés demandent la démission de l’entraîneur, du chef de la fédération et, par précaution, du ministre des Sports. Quel est votre pronostic ?","answers":[{"tone":"franche","label":"Nous perdons parce que nous avons négligé la formation des jeunes. Je finance les clubs de quartier et je demande des comptes à la fédération.","effects":{"cohesion":5,"budget":-3},"news":"Football : le Chancelier finance les clubs de quartier","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les petits clubs reçoivent enfin des ballons neufs"}]},{"tone":"langue-de-bois","label":"Le sport est un vecteur de cohésion et de fierté collective, et nous soutenons l’ensemble des acteurs du football avec confiance et enthousiasme.","effects":{"cohesion":2,"popularite":-2},"news":"Football : le Chancelier soutient tout le monde « avec enthousiasme »"},{"tone":"offensive","label":"Les bistrots peuvent bien réclamer des démissions, mais qui d’entre eux a déjà couru quatre-vingt-dix minutes sans pause pour demander un remplacement ?","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"news":"Le Chancelier aux cafés : « Courez quatre-vingt-dix minutes »","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les supporters forment un cortège bruyant mais correct"}]}]},{"id":"allemagne-q-pain-saucisse","theme":"popularite","text":"Un guide prétend que votre pays compte plus de trois mille variétés de pain et autant de saucisses. Seriez-vous prêt à en prendre une comme emblème officiel ou l’unité nationale en sortirait-elle brisée ?","answers":[{"tone":"franche","label":"Je ne choisirai aucune, par prudence. En revanche, je soutiens les boulangers artisanaux, car le pain est aussi une affaire d’emploi local.","effects":{"cohesion":4,"economie":2,"budget":-3},"news":"Pain et saucisse : le Chancelier refuse de trancher mais aide les boulangers","delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Un syndicat de charcutiers se déclare vexé"}]},{"tone":"langue-de-bois","label":"Notre patrimoine culinaire est vaste, divers et vivant, et chaque variété mérite d’être reconnue au sein d’un ensemble harmonieux.","effects":{"cohesion":2,"popularite":-2},"news":"Le Chancelier : chaque saucisse mérite « sa place dans l’ensemble »"},{"tone":"offensive","label":"Je choisis mon pain du matin avec courage, et mon saucisson le soir avec hauteur. Ceux qui hésitent n’ont jamais goûté à la coalition.","effects":{"popularite":5,"cohesion":-3,"international":-2},"news":"Le Chancelier : « Je choisis mon pain avec courage »","delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Le Bundestag consacre trois heures à la moutarde"}]}]},{"id":"allemagne-q-fax-administratif","theme":"popularite","text":"Dans certaines administrations, le fax règne toujours en maître, entouré d’un tampon et d’un classeur. Votre promesse de numériser l’État sera-t-elle livrée avant que le dernier fax ne rende l’âme ?","answers":[{"tone":"franche","label":"Je préfère ne pas promettre de date. Nous avons du retard, je lance un chantier concret et je publierai chaque trimestre l’état d’avancement.","effects":{"popularite":4,"budget":-3},"news":"Numérique : le Chancelier publiera l’avancement chaque trimestre","delayed":[{"delay":3,"effects":{"economie":2},"label":"Les entreprises voient enfin passer un formulaire en ligne"}]},{"tone":"langue-de-bois","label":"La transformation numérique est un chantier prioritaire, ambitieux et collectif, qui s’inscrit dans la durée avec une attention constante.","effects":{"popularite":2,"economie":-2},"news":"Numérique : le fax survit à la « transformation »"},{"tone":"offensive","label":"Ceux qui défendent le fax sont des collectionneurs ou des fonctionnaires nostalgiques. Je leur donne un an pour passer à l’ère du courriel, sans accuser réception.","effects":{"economie":4,"popularite":2,"cohesion":-4},"news":"Le Chancelier donne un an au fax pour disparaître","delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les syndicats de fonctionnaires déposent un recours… par fax"}]}]},{"id":"allemagne-q-recyclage-consigne","theme":"international","text":"Un pays voisin admire votre système de consigne et de tri, mais ne comprend toujours pas pourquoi une bouteille a quatre poubelles et trois couleurs. Allez-vous exporter ce modèle ?","answers":[{"tone":"franche","label":"Volontiers, mais en le simplifiant. Un modèle qui exige un manuel de trente pages n’est pas un modèle, c’est une épreuve.","effects":{"international":4,"ecologie":2,"economie":-3},"news":"Recyclage : le Chancelier veut exporter un modèle « simplifié »","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les voisins envoient une délégation avec un classeur"}]},{"tone":"langue-de-bois","label":"Notre expérience en matière de gestion des déchets est un atout partagé que nous mettrons à disposition de nos partenaires dans un esprit de coopération.","effects":{"international":2,"ecologie":-2},"news":"Recyclage : « un atout partagé » mis à disposition des voisins"},{"tone":"offensive","label":"Les pays qui jettent tout au même endroit devraient apprendre à trier avant de donner des leçons. Je leur offre quatre poubelles, gratuitement.","effects":{"ecologie":5,"popularite":3,"international":-5},"news":"Le Chancelier offre « quatre poubelles » aux pays qui trient mal","delayed":[{"delay":2,"effects":{"international":-2},"label":"Une ambassade proteste par une note… en quatre exemplaires"}]}]},{"id":"allemagne-q-fiere-vacances","theme":"cohesion","text":"Votre pays ferme pour les vacances scolaires, étalées région par région pour éviter les bouchons, mais personne n’est jamais d’accord sur les dates. Allez-vous trancher pour un calendrier fédéral ?","answers":[{"tone":"franche","label":"Non. Chaque Land garde la main, mais nous publierons le calendrier un an avant. Les familles méritent de réserver leur plage sans lire un traité.","effects":{"cohesion":4,"assemblee":-3},"news":"Vacances scolaires : le Chancelier laisse la main aux Länder mais veut un calendrier lisible","delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les familles applaudissent sur le parking de l’autoroute"}]},{"tone":"langue-de-bois","label":"Le calendrier scolaire est un compromis délicat entre les aspirations des familles, les contraintes économiques et la diversité régionale.","effects":{"cohesion":2,"popularite":-2},"news":"Vacances : un « compromis délicat », donc pas de date"},{"tone":"offensive","label":"Les régions qui veulent des vacances plus longues n’ont qu’à proposer des examens plus courts. Nous en reparlerons pendant les prochaines vacances, à la mer.","effects":{"popularite":4,"assemblee":-3,"cohesion":-3},"news":"Le Chancelier aux régions : « Proposez des examens plus courts »","delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les ministres régionaux de l’éducation bloquent le sujet"}]}]},{"id":"allemagne-q-retraites-demographie","theme":"pouvoirAchat","text":"Le pays vieillit, les retraites coûtent cher, et les jeunes se demandent s’ils toucheront un jour autre chose qu’un conseil d’épargne. Faut-il travailler plus longtemps, cotiser davantage ou prier ?","answers":[{"tone":"franche","label":"Un peu des deux premières options, et un fonds d’épargne collectif pour ne pas prier seuls. Rien n’est gratuit, mais tout peut être équitable.","effects":{"budget":4,"popularite":-3,"pouvoirAchat":-3},"news":"Retraites : le Chancelier évoque un fonds collectif et un effort partagé","delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les jeunes saluent un débat enfin sans tabou"}]},{"tone":"langue-de-bois","label":"Le système de retraite repose sur un pacte de solidarité entre les générations que nous réaffirmons avec force, clarté et responsabilité.","effects":{"pouvoirAchat":2,"budget":-2},"news":"Retraites : le « pacte entre générations » réaffirmé, mais pas précisé"},{"tone":"offensive","label":"Ceux qui promettent des retraites sans financement vendent du rêve en gros. Je préfère un pays honnête avec des cheveux gris qu’un pays endormi.","effects":{"budget":5,"assemblee":2,"popularite":-4,"cohesion":-3},"news":"Le Chancelier : « Je préfère un pays honnête aux cheveux gris »","delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les syndicats proposent un cortège de retraités à vélo"}]}]},{"id":"allemagne-q-ecole-numerique","theme":"international","text":"Des enseignants étrangers viennent étudier votre système de formation en alternance, mais ils vous demandent pourquoi les écoles n’ont pas encore de réseau fiable. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"Que l’alternance est un atout, mais que nous avons pris du retard sur le numérique. Je finance les réseaux d’abord, les discours de rentrée ensuite.","effects":{"international":3,"economie":2,"budget":-4},"news":"Écoles : le Chancelier avoue le retard numérique et finance les réseaux","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les enseignants testent enfin une visioconférence qui tient"}]},{"tone":"langue-de-bois","label":"Notre modèle de formation est reconnu internationalement, et nous poursuivons sa modernisation dans le cadre d’un partenariat renouvelé avec les Länder.","effects":{"international":2,"popularite":-2},"news":"Le Chancelier : « modernisation dans un partenariat renouvelé »"},{"tone":"offensive","label":"Les visiteurs sont priés de comparer nos apprentis avec leurs diplômés sans emploi. Nos écoles n’ont peut-être pas de réseau, mais leurs sorties ont un avenir.","effects":{"popularite":4,"international":-5,"assemblee":-2},"news":"Le Chancelier défie les visiteurs : « Comparez nos apprentis »","delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les enseignants jugent la comparaison peu pédagogique"}]}]},{"id":"allemagne-q-transition-ruhr","theme":"crise","text":"Une région industrielle craint le chômage de masse après la fermeture d’une grande aciérie, et les élus demandent des garanties. La reconversion est-elle un mot ou un plan ?","answers":[{"tone":"franche","label":"C’est un plan que nous devons financer, avec des formations, des zones d’activité et un suivi public. Je ne promets pas de sauver chaque poste.","effects":{"cohesion":5,"economie":2,"budget":-5},"news":"Aciérie : le Chancelier promet formations et zones d’activité","delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les premiers stagiaires obtiennent leur certificat… en triple exemplaire"}]},{"tone":"langue-de-bois","label":"Nous accompagnerons la région dans cette phase de mutation avec toute l’attention, l’écoute et l’engagement qui s’imposent.","effects":{"cohesion":2,"popularite":-3},"news":"Aciérie : « toute l’attention qui s’impose » pour la région"},{"tone":"offensive","label":"Les élus qui exigent des garanties devraient d’abord garantir qu’ils ne voteront pas contre le plan. Je mettrai les crédits où l’on m’aidera à avancer.","effects":{"assemblee":4,"budget":3,"cohesion":-5},"news":"Le Chancelier aux élus de la région : « Aidez-moi à avancer »","delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Une délégation d’ouvriers vient déposer une clef à molette"}]}]},{"id":"allemagne-q-sante-urgences","theme":"securite","text":"Le système de santé est réputé efficace, mais les urgences des hôpitaux affichent des délais d’attente qui ressemblent à des numéros de loterie. Où est la faille ?","answers":[{"tone":"franche","label":"Dans le manque de personnel et la gestion cloisonnée entre cliniques, médecins de ville et hôpitaux. Je lance une réforme qui fâchera plusieurs lobbies.","effects":{"securite":5,"budget":-3,"assemblee":-3},"news":"Urgences : le Chancelier lance une réforme qui « fâchera plusieurs lobbies »","delayed":[{"delay":3,"effects":{"popularite":3},"label":"Les premières files d’attente raccourcissent, d’une minute"}]},{"tone":"langue-de-bois","label":"Notre système de santé repose sur des professionnels remarquables, et nous veillons à l’adapter en continu aux besoins de la population.","effects":{"securite":2,"popularite":-2},"news":"Urgences : le Chancelier remercie les professionnels, sans plan"},{"tone":"offensive","label":"Les critiques voudraient un hôpital par village, mais personne ne veut payer le village. Je construis des pôles d’excellence, pas des gares de fortune.","effects":{"securite":4,"economie":3,"cohesion":-5,"popularite":-2},"news":"Le Chancelier : « Des pôles d’excellence, pas des gares de fortune »","delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les petites communes organisent une marche en blouse blanche"}]}]}]}'),u={pays:e,version:1,textes:n,institutions:s,election:a,lois:t,crises:i,missions:r,presse:l};export{i as crises,u as default,a as election,s as institutions,t as lois,r as missions,e as pays,l as presse,n as textes,o as version};
